//! Named-pipe IPC servers (T-31–T-34).
//!
//! Three named pipes connect the DLP Agent service to the UI process:
//!
//! | Pipe | Name                     | Direction   | Purpose                            |
//! |------|--------------------------|-------------|------------------------------------|
//! | P1   | `\\.\pipe\DLPCommand`   | Bidirectional | BLOCK_NOTIFY, OVERRIDE_REQUEST, CLIPBOARD_READ, PASSWORD_DIALOG |
//! | P2   | `\\.\pipe\DLPEventAgent2UI` | Agent → UI | TOAST, STATUS_UPDATE, HEALTH_PING, UI_RESPAWN, UI_CLOSING_SEQUENCE |
//! | P3   | `\\.\pipe\DLPEventUI2Agent` | UI → Agent | HEALTH_PONG, UI_READY, UI_CLOSING |
//!
//! All pipes use JSON messages over a synchronous byte stream.
//! The `windows` crate's named-pipe APIs (`CreateNamedPipeW`, `ConnectNamedPipe`,
//! `ReadFile`, `WriteFile`) are used directly via `spawn_blocking` so they do not
//! block the async runtime.

pub mod frame;
pub mod messages;
pub mod pipe1;
pub mod pipe2;
pub mod pipe3;
pub mod pipe_security;
pub mod server;

pub use server::start_all;

//! Length-prefixed JSON frame helpers for named-pipe IPC (T-32).
//!
//! Each frame on every pipe is encoded as:
//! ```text
//! [u32: payload_length_le] [payload_bytes]
//! ```
//!
//! The payload is a UTF-8 JSON document — exactly what `serde_json` produces.

use anyhow::{Context, Result};
use windows::Win32::Foundation::HANDLE;
use windows::Win32::Storage::FileSystem::{FlushFileBuffers, ReadFile, WriteFile};

/// Reads a single length-prefixed frame from a pipe handle.
//
// # Errors
// Returns an error if the pipe is broken, the frame header cannot be read,
// or fewer bytes than declared are received.
pub fn read_frame(pipe: HANDLE) -> Result<Vec<u8>> {
    let mut length_buf = [0u8; 4];
    read_exact(pipe, &mut length_buf).context("read frame length")?;

    let payload_len = u32::from_le_bytes(length_buf) as usize;

    // Guard against degenerate frames (64 MiB max — prevents a misbehaving
    // client from exhausting memory).
    const MAX_PAYLOAD: usize = 67_108_864;
    if payload_len > MAX_PAYLOAD {
        return Err(anyhow::anyhow!(
            "frame payload too large: {} bytes (max 64 MiB)",
            payload_len
        ));
    }

    let mut payload = vec![0u8; payload_len];
    read_exact(pipe, &mut payload).context("read frame payload")?;
    Ok(payload)
}

/// Writes a length-prefixed frame to a pipe handle.
//
// # Errors
// Returns an error if the pipe is broken or the write is partial.
pub fn write_frame(pipe: HANDLE, payload: &[u8]) -> Result<()> {
    let length_buf = (payload.len() as u32).to_le_bytes();
    write_all(pipe, &length_buf).context("write frame length")?;
    write_all(pipe, payload).context("write frame payload")?;

    // Flush so the client receives data before we wait for the next message.
    flush(pipe).context("flush frame")?;

    Ok(())
}

/// Like [`std::io::Read::read_exact`] but for Win32 [`HANDLE`].
fn read_exact(pipe: HANDLE, buf: &mut [u8]) -> Result<()> {
    let mut remaining = buf.len();

    while remaining > 0 {
        let slice_len = remaining.min(65536);
        let offset = buf.len() - remaining;
        let mut bytes_read = 0u32;

        // windows-rs 0.58 ReadFile: lpbuffer: Option<&mut [u8]>
        let result = unsafe {
            ReadFile(
                pipe,
                Some(&mut buf[offset..offset + slice_len]),
                Some(&mut bytes_read),
                None,
            )
        };

        if result.is_err() {
            return Err(anyhow::anyhow!(
                "ReadFile returned an error ({} bytes read before failure)",
                buf.len() - remaining
            ));
        }

        if bytes_read == 0 {
            return Err(anyhow::anyhow!(
                "pipe closed prematurely ({} bytes read, {} expected)",
                buf.len() - remaining,
                buf.len()
            ));
        }

        remaining -= bytes_read as usize;
    }

    Ok(())
}

/// Like [`std::io::Write::write_all`] but for Win32 [`HANDLE`].
fn write_all(pipe: HANDLE, buf: &[u8]) -> Result<()> {
    let mut remaining = buf.len();

    while remaining > 0 {
        let mut bytes_written = 0u32;
        let slice_len = buf.len() - remaining;

        // windows-rs 0.58 WriteFile: lpbuffer: Option<&[u8]>
        let result = unsafe {
            WriteFile(
                pipe,
                Some(&buf[..slice_len]),
                Some(&mut bytes_written),
                None,
            )
        };

        if result.is_err() {
            return Err(anyhow::anyhow!(
                "WriteFile returned an error ({} bytes written before failure)",
                buf.len() - remaining
            ));
        }

        if bytes_written == 0 {
            return Err(anyhow::anyhow!(
                "pipe closed during write ({} bytes written, {} expected)",
                buf.len() - remaining,
                buf.len()
            ));
        }

        remaining -= bytes_written as usize;
    }

    Ok(())
}

/// Flushes write buffers for a pipe handle.
fn flush(pipe: HANDLE) -> Result<()> {
    unsafe { FlushFileBuffers(pipe).map_err(|e| anyhow::anyhow!("FlushFileBuffers failed: {}", e)) }
}

//! Named-pipe security descriptor for Agent-to-UI IPC.
//!
//! Creates a `SECURITY_ATTRIBUTES` that grants Authenticated Users
//! read/write access to the pipe, allowing the dlp-user-ui process
//! (running as the interactive user) to connect to pipes owned by the
//! dlp-agent service (running as SYSTEM).
//!
//! Uses an SDDL string to define the DACL, which is simpler and more
//! reliable than building ACL entries manually.

use windows::core::PCWSTR;
use windows::Win32::Security::Authorization::ConvertStringSecurityDescriptorToSecurityDescriptorW;
use windows::Win32::Security::{PSECURITY_DESCRIPTOR, SECURITY_ATTRIBUTES};

/// SDDL string granting:
/// - `(A;;GRGW;;;AU)` — Allow Generic Read + Generic Write to
///   Authenticated Users
/// - `(A;;GA;;;SY)` — Allow Generic All to SYSTEM
/// - `(A;;GA;;;BA)` — Allow Generic All to Built-in Administrators
///
/// This lets the interactive-user UI process connect to SYSTEM-owned
/// pipes while preserving full control for SYSTEM and Administrators.
const PIPE_SDDL: &str = "D:(A;;GRGW;;;AU)(A;;GA;;;SY)(A;;GA;;;BA)\0";

/// A self-contained pipe security context that owns the security
/// descriptor buffer.
///
/// The `SECURITY_ATTRIBUTES` returned by [`as_ptr`](Self::as_ptr) is
/// valid for the lifetime of this struct.  Drop it only after
/// `CreateNamedPipeW` returns.
pub struct PipeSecurity {
    /// The raw SD pointer allocated by
    /// `ConvertStringSecurityDescriptorToSecurityDescriptorW`.
    /// Must be freed with `LocalFree`.
    sd_ptr: PSECURITY_DESCRIPTOR,
    /// The `SECURITY_ATTRIBUTES` struct pointing to `sd_ptr`.
    sa: SECURITY_ATTRIBUTES,
}

impl PipeSecurity {
    /// Builds a `SECURITY_ATTRIBUTES` that allows Authenticated Users
    /// to read and write the pipe.
    ///
    /// # Returns
    ///
    /// A `PipeSecurity` whose [`as_ptr`](Self::as_ptr) can be passed
    /// to `CreateNamedPipeW`.
    ///
    /// # Errors
    ///
    /// Returns an error if the SDDL conversion fails.
    pub fn new() -> anyhow::Result<Self> {
        let sddl_wide: Vec<u16> = PIPE_SDDL.encode_utf16().collect();

        let mut sd_ptr = PSECURITY_DESCRIPTOR::default();

        // SAFETY: ConvertStringSecurityDescriptorToSecurityDescriptorW
        // parses a well-known SDDL string and allocates the SD via
        // LocalAlloc.  We free it in Drop.
        unsafe {
            ConvertStringSecurityDescriptorToSecurityDescriptorW(
                PCWSTR::from_raw(sddl_wide.as_ptr()),
                1, // SDDL_REVISION_1
                &mut sd_ptr,
                None,
            )
            .map_err(|e| anyhow::anyhow!("SDDL security descriptor creation failed: {e}"))?;
        }

        let sa = SECURITY_ATTRIBUTES {
            nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
            lpSecurityDescriptor: sd_ptr.0,
            bInheritHandle: false.into(),
        };

        Ok(Self { sd_ptr, sa })
    }

    /// Returns a pointer to the `SECURITY_ATTRIBUTES`.
    ///
    /// Valid for the lifetime of this `PipeSecurity` instance.
    pub fn as_ptr(&self) -> *const SECURITY_ATTRIBUTES {
        &self.sa
    }
}

impl Drop for PipeSecurity {
    fn drop(&mut self) {
        if !self.sd_ptr.0.is_null() {
            // SAFETY: sd_ptr was allocated by
            // ConvertStringSecurityDescriptorToSecurityDescriptorW
            // via LocalAlloc.
            unsafe {
                let _ = windows::Win32::Foundation::LocalFree(Some(
                    windows::Win32::Foundation::HLOCAL(self.sd_ptr.0),
                ));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pipe_security_creates_successfully() {
        let sec = PipeSecurity::new();
        assert!(sec.is_ok(), "PipeSecurity::new() should succeed");
    }

    #[test]
    fn test_pipe_security_as_ptr_non_null() {
        let sec = PipeSecurity::new().unwrap();
        assert!(!sec.as_ptr().is_null());
    }
}

//! Pipe 1 — `\\.\pipe\DLPCommand` — bidirectional command pipe (T-32).
//!
//! The agent accepts BLOCK_NOTIFY, OVERRIDE_REQUEST, CLIPBOARD_READ,
//! and PASSWORD_DIALOG from the UI and responds with USER_CONFIRMED,
//! USER_CANCELLED, CLIPBOARD_DATA, PASSWORD_SUBMIT.
//!
//! ## Server-initiated messages
//!
//! The agent can also send messages to connected UI clients (e.g. PASSWORD_DIALOG
//! when `sc stop` is issued).  Connected client handles are tracked by session ID
//! so server-initiated messages can be routed to the correct UI process.

use std::collections::HashMap;
use std::sync::Arc;

use anyhow::{Context, Result};
use once_cell::sync::Lazy;
use parking_lot::RwLock;
use tracing::{debug, error, info, warn};
use windows::core::PCWSTR;
use windows::Win32::Foundation::{CloseHandle, HANDLE};
use windows::Win32::Storage::FileSystem::PIPE_ACCESS_DUPLEX;
use windows::Win32::System::Pipes::{
    ConnectNamedPipe, CreateNamedPipeW, DisconnectNamedPipe, NAMED_PIPE_MODE,
    PIPE_READMODE_MESSAGE, PIPE_TYPE_MESSAGE, PIPE_WAIT,
};

use super::frame::{read_frame, write_frame};
use super::messages::{Pipe1AgentMsg, Pipe1UiMsg};

/// Pending clipboard-read request IDs awaiting data from the UI.
///
/// The clipboard read request is initiated by the interception layer (which calls
/// [`crate::clipboard::listener::read_clipboard_request`]).  When the UI sends
/// `ClipboardData`, the data is stored here and the interception handler wakes up.
static CLIPBOARD_CACHE: Lazy<Arc<RwLock<HashMap<String, String>>>> =
    Lazy::new(|| Arc::new(RwLock::new(HashMap::new())));

/// Pending override requests awaiting user confirmation or cancellation.
///
/// When the agent needs user override confirmation, it stores the request context
/// here.  `UserConfirmed` clears the entry and proceeds; `UserCancelled` clears
/// and aborts the operation.
static OVERRIDE_PENDING: Lazy<Arc<RwLock<HashMap<String, OverrideContext>>>> =
    Lazy::new(|| Arc::new(RwLock::new(HashMap::new())));

/// Context stored for a pending override request.
#[derive(Debug)]
struct OverrideContext {
    /// The session ID of the requesting session.
    session_id: u32,
    /// When the request was created (for timeout detection).
    created_at: std::time::Instant,
}

/// Returns a snapshot of all pending clipboard request IDs.
pub fn get_pending_clipboard_requests() -> Vec<String> {
    CLIPBOARD_CACHE.read().keys().cloned().collect()
}

/// Retrieves and removes clipboard data for a given request ID.
///
/// Returns `None` if no data is available yet.  Callers should retry after a
/// short delay if `None` is returned.
pub fn take_clipboard_data(request_id: &str) -> Option<String> {
    CLIPBOARD_CACHE.write().remove(request_id)
}

/// Makes `HANDLE` `Send + Sync` so it can be stored in a static `HashMap`.
///
/// Safety: all mutations go through `RwLock` and are confined to the
/// single-threaded pipe server.
struct SendableHandle(HANDLE);

impl SendableHandle {
    fn new(h: HANDLE) -> Self {
        Self(h)
    }
    fn as_handle(&self) -> HANDLE {
        self.0
    }
}

unsafe impl Send for SendableHandle {}
unsafe impl Sync for SendableHandle {}

/// The Win32 pipe name.
const PIPE_NAME: &str = r"\\.\pipe\DLPCommand";

/// The number of pipe instances to create.
const NUM_INSTANCES: u32 = 4;

/// Tracks connected Pipe 1 client handles by session ID.
///
/// A Pipe 1 connection is session-scoped (one UI per session connects to
/// Pipe 1 when it starts).  The agent uses this map to send server-initiated
/// messages (e.g. PASSWORD_DIALOG) to the correct session's UI.
static CLIENTS: std::sync::LazyLock<RwLock<HashMap<u32, SendableHandle>>> =
    std::sync::LazyLock::new(|| RwLock::new(HashMap::new()));

/// Combines the pipe-mode flags into a single `NAMED_PIPE_MODE` value.
fn pipe_mode() -> NAMED_PIPE_MODE {
    PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT
}

/// Serves Pipe 1 with a readiness callback.
///
/// `on_ready` is called after the first `CreateNamedPipeW` succeeds,
/// signalling that the pipe exists and clients can connect.
pub fn serve_with_ready(on_ready: impl FnOnce()) -> Result<()> {
    info!(pipe = PIPE_NAME, "Pipe 1 server starting");
    let first_pipe = create_pipe()?;
    on_ready();
    accept_loop(first_pipe)
}

/// Serves Pipe 1 without a readiness callback.
pub fn serve() -> Result<()> {
    info!(pipe = PIPE_NAME, "Pipe 1 server starting");
    accept_loop(create_pipe()?)
}

/// Accept loop: waits for clients, handles them, then creates a new
/// pipe instance for the next client.
fn accept_loop(first_pipe: HANDLE) -> Result<()> {
    let mut pipe = first_pipe;
    loop {
        // Wait for a client to connect.  ConnectNamedPipe returns
        // ERROR_PIPE_CONNECTED if a client connected between
        // CreateNamedPipeW and this call — that is a success case.
        if let Err(e) = unsafe { ConnectNamedPipe(pipe, None) } {
            let win32_code = (e.code().0 as u32) & 0xFFFF;
            if win32_code != 535 {
                warn!(win32_code, "ConnectNamedPipe failed — recycling pipe");
                let _ = unsafe { CloseHandle(pipe) };
                pipe = create_pipe()?;
                continue;
            }
            debug!("ConnectNamedPipe: client already connected (535)");
        }

        info!(pipe = PIPE_NAME, "client connected to Pipe 1");
        let _ = handle_client(pipe);

        // Create a new pipe instance for the next client.
        pipe = create_pipe()?;
    }
}

/// Creates a new named pipe instance with a DACL that allows
/// Authenticated Users (the interactive-user UI process) to connect.
fn create_pipe() -> Result<HANDLE> {
    let name_wide: Vec<u16> = PIPE_NAME.encode_utf16().chain(std::iter::once(0)).collect();

    // Build a security descriptor that grants Authenticated Users
    // read/write access so the user-context UI can connect.
    let sec = super::pipe_security::PipeSecurity::new().context("pipe security descriptor")?;

    let pipe = unsafe {
        CreateNamedPipeW(
            PCWSTR::from_raw(name_wide.as_ptr()),
            PIPE_ACCESS_DUPLEX,
            pipe_mode(),
            NUM_INSTANCES,
            65536, // output buffer
            65536, // input buffer
            5000,  // default timeout ms
            Some(sec.as_ptr()),
        )
    };

    if pipe.is_invalid() {
        return Err(anyhow::anyhow!(
            "CreateNamedPipeW returned INVALID_HANDLE_VALUE"
        ));
    }

    Ok(pipe)
}

/// Handles a single client connection.
fn handle_client(pipe: HANDLE) -> Result<()> {
    // The first message MUST be RegisterSession so we know which session owns this pipe.
    let frame = match read_frame(pipe) {
        Ok(f) => f,
        Err(e) => {
            debug!(error = %e, "Pipe 1: first-frame read error — disconnecting");
            return cleanup_pipe(pipe);
        }
    };

    let msg: Pipe1UiMsg = match serde_json::from_slice(&frame) {
        Ok(m) => m,
        Err(e) => {
            error!(error = %e, "Pipe 1: failed to deserialise first message");
            return cleanup_pipe(pipe);
        }
    };

    // Extract session ID from the registration message.
    let Pipe1UiMsg::RegisterSession { session_id } = msg else {
        error!("Pipe 1: first message must be RegisterSession");
        return cleanup_pipe(pipe);
    };

    info!(session_id, "Pipe 1: UI registered");
    CLIENTS
        .write()
        .insert(session_id, SendableHandle::new(pipe));

    let result = client_loop(session_id, pipe);

    // Remove from client map on disconnect.
    CLIENTS.write().remove(&session_id);
    cleanup_pipe(pipe)?;

    result
}

/// The read loop for a connected Pipe 1 client.
fn client_loop(session_id: u32, pipe: HANDLE) -> Result<()> {
    loop {
        let frame = match read_frame(pipe) {
            Ok(f) => f,
            Err(e) => {
                debug!(session_id, error = %e, "Pipe 1: read error — disconnecting");
                break;
            }
        };

        let msg: Pipe1UiMsg = match serde_json::from_slice(&frame) {
            Ok(m) => m,
            Err(e) => {
                error!(error = %e, "Pipe 1: failed to deserialise message");
                continue;
            }
        };

        debug!(?msg, "Pipe 1: received from UI");

        // Dispatch the message (skip RegisterSession — already handled).
        if !matches!(msg, Pipe1UiMsg::RegisterSession { .. }) {
            let response = dispatch(msg);
            if let Some(resp) = response {
                if let Err(e) = write_frame(pipe, &resp) {
                    error!(session_id, error = %e, "Pipe 1: failed to write response");
                    break;
                }
            }
        }
    }

    Ok(())
}

/// Closes and disconnects a pipe handle.
fn cleanup_pipe(pipe: HANDLE) -> Result<()> {
    unsafe {
        let _ = DisconnectNamedPipe(pipe);
        let _ = CloseHandle(pipe);
    }
    Ok(())
}

/// Dispatches an incoming UI message and returns an optional JSON response.
fn dispatch(msg: Pipe1UiMsg) -> Option<Vec<u8>> {
    match msg {
        Pipe1UiMsg::RegisterSession { .. } => {
            // Already handled in handle_client — should not reach dispatch.
            None
        }
        Pipe1UiMsg::UserConfirmed { request_id } => {
            info!(request_id, "Pipe 1: UI confirmed action");
            // Remove any pending clipboard data associated with this request.
            let _ = CLIPBOARD_CACHE.write().remove(&request_id);

            // If this was an override confirmation, emit an override-granted
            // audit event for the compliance trail.  The file operation itself
            // is not retried (notify watcher is observe-only; actual blocking
            // requires a kernel-level minifilter in a future phase).
            let removed = OVERRIDE_PENDING.write().remove(&request_id);
            if let Some(ctx) = removed {
                warn!(
                    request_id,
                    session_id = ctx.session_id,
                    elapsed_ms = ctx.created_at.elapsed().as_millis() as u64,
                    "Pipe 1: override confirmed — audit event emitted"
                );
                // Emit an override-granted audit event.
                let event = dlp_common::AuditEvent::new(
                    dlp_common::EventType::Access,
                    "OVERRIDE".to_string(),
                    "OVERRIDE".to_string(),
                    request_id.clone(),
                    dlp_common::Classification::T1,
                    dlp_common::Action::READ,
                    dlp_common::Decision::AllowWithLog,
                    "AGENT".to_string(),
                    ctx.session_id,
                )
                .with_override_granted();
                let ctx = crate::audit_emitter::EmitContext {
                    agent_id: "AGENT".to_string(),
                    session_id: ctx.session_id,
                    user_sid: "OVERRIDE".to_string(),
                    user_name: "OVERRIDE".to_string(),
                    machine_name: None,
                };
                crate::audit_emitter::emit_audit(&ctx, &mut event.clone());
            } else {
                debug!(
                    request_id,
                    "Pipe 1: UserConfirmed for unknown request — ignored"
                );
            }
            None
        }
        Pipe1UiMsg::UserCancelled { request_id } => {
            info!(request_id, "Pipe 1: UI cancelled action");
            // Remove pending clipboard data and override context.
            let _ = CLIPBOARD_CACHE.write().remove(&request_id);
            if let Some(ctx) = OVERRIDE_PENDING.write().remove(&request_id) {
                warn!(
                    request_id,
                    session_id = ctx.session_id,
                    elapsed_ms = ctx.created_at.elapsed().as_millis() as u64,
                    "Pipe 1: override cancelled by user — operation aborted"
                );
            }
            None
        }
        Pipe1UiMsg::ClipboardData { request_id, data } => {
            info!(
                request_id,
                data_len = data.len(),
                "Pipe 1: clipboard data received — storing for retrieval"
            );
            // Store the clipboard data so the interception handler can retrieve it
            // after waking from its await.  Trim whitespace to avoid matching on
            // accidental whitespace-only pastes.
            let trimmed = data.trim().to_string();
            if !trimmed.is_empty() {
                CLIPBOARD_CACHE.write().insert(request_id.clone(), trimmed);
            } else {
                debug!(request_id, "Pipe 1: clipboard data is empty — ignoring");
            }
            None
        }
        Pipe1UiMsg::PasswordSubmit {
            request_id,
            password,
        } => {
            info!(request_id, "Pipe 1: password submitted");
            // Pipe-based flow uses DPAPI-wrapped passwords.
            crate::password_stop::handle_password_submit(&request_id, password, false);
            None
        }
        Pipe1UiMsg::PasswordCancel { request_id } => {
            info!(request_id, "Pipe 1: password dialog cancelled");
            crate::password_stop::handle_password_cancel(&request_id);
            None
        }
        Pipe1UiMsg::Pong => {
            debug!("Pipe 1: Pong received");
            None
        }
    }
}

/// Sends a Pipe1AgentMsg to the UI in a specific session (fire-and-forget).
///
/// The session ID determines which connected UI client receives the message.
/// If no client is registered for that session the message is silently dropped.
pub fn send_to_ui(session_id: u32, msg: &Pipe1AgentMsg) -> Result<()> {
    let pipe = match CLIENTS.read().get(&session_id).map(|h| h.as_handle()) {
        Some(h) => h,
        None => {
            debug!(
                session_id,
                "Pipe 1: no client for session — dropping message"
            );
            return Ok(());
        }
    };

    let json = serde_json::to_vec(msg).context("serialise Pipe1AgentMsg")?;
    write_frame(pipe, &json).inspect_err(|e| debug!(session_id, error = %e, "Pipe 1: write failed"))
}

/// Sends a PASSWORD_DIALOG to the UI in all connected sessions.
///
/// Used by [`crate::password_stop`] when the service receives `sc stop`.
///
/// # Returns
///
/// The number of UI clients that successfully received the message.
/// Returns `0` when no clients are connected (caller should spawn a UI).
pub fn send_password_dialog(request_id: &str) -> Result<u32> {
    let msg = Pipe1AgentMsg::PasswordDialog {
        request_id: request_id.to_string(),
    };

    let json = serde_json::to_vec(&msg).context("serialise PASSWORD_DIALOG")?;

    let clients = CLIENTS.read();
    let count = clients.len();
    let mut ok_count: u32 = 0;

    for (sid, handle) in clients.iter() {
        match write_frame(handle.as_handle(), &json) {
            Ok(()) => ok_count += 1,
            Err(e) => {
                debug!(session_id = sid, error = %e, "Pipe 1: PASSWORD_DIALOG write failed");
            }
        }
    }

    if count == 0 {
        info!("Pipe 1: no UI clients connected — PASSWORD_DIALOG not sent");
    } else {
        info!(
            sessions_contacted = count,
            sessions_reached = ok_count,
            "Pipe 1: PASSWORD_DIALOG sent"
        );
    }

    Ok(ok_count)
}

/// Returns the number of currently connected Pipe 1 clients.
pub fn connected_client_count() -> usize {
    CLIENTS.read().len()
}

/// Sends a `Ping` heartbeat to all connected Pipe 1 clients.
///
/// Used by the agent's heartbeat task to verify UI liveness.
/// Clients that do not respond within the UI-side timeout will self-terminate.
pub fn send_ping_to_all() {
    let msg = Pipe1AgentMsg::Ping;
    let json = match serde_json::to_vec(&msg) {
        Ok(j) => j,
        Err(e) => {
            debug!(error = %e, "Pipe 1: failed to serialise Ping");
            return;
        }
    };

    let clients = CLIENTS.read();
    for (sid, handle) in clients.iter() {
        if let Err(e) = write_frame(handle.as_handle(), &json) {
            debug!(session_id = sid, error = %e, "Pipe 1: Ping write failed");
        }
    }
}

//! IPC message types shared between the agent and UI.
//!
//! All messages are JSON-encoded and delimited by a 4-byte little-endian length prefix.
//! A frame is: `[u32:length][json:payload]` — exactly what `serde_json` produces when
//! combined with a manual length-prefix write/read.

use dlp_common::AppIdentity;
use serde::{Deserialize, Serialize};

// ─────────────────────────────────────────────────────────────────────────────
// Pipe 1 — DLPCommand (bidirectional)
// ─────────────────────────────────────────────────────────────────────────────

/// Messages sent FROM the agent TO the UI over Pipe 1.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload")]
pub enum Pipe1AgentMsg {
    /// The agent blocked an operation — UI should display a notification.
    BlockNotify {
        reason: String,
        classification: String,
        resource_path: String,
        policy_id: String,
    },
    /// The user requested an override — UI should show a justification dialog.
    OverrideRequest {
        request_id: String,
        reason: String,
        classification: String,
        resource_path: String,
    },
    /// The agent needs to read the clipboard — UI should return the data.
    ClipboardRead { request_id: String },
    /// The agent is requesting a password (for service stop authorization).
    PasswordDialog { request_id: String },
    /// Heartbeat ping sent periodically to verify the UI is still responsive.
    /// The UI should respond with `Pong` or silently continue; missing pings
    /// trigger the watchdog self-terminate path.
    Ping,
}

/// Messages sent FROM the UI TO the agent over Pipe 1.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload")]
pub enum Pipe1UiMsg {
    /// The UI registered itself with its session ID (sent as the first message
    /// after connecting to Pipe 1).
    RegisterSession { session_id: u32 },
    /// The user confirmed the block (override granted).
    UserConfirmed { request_id: String },
    /// The user cancelled the override request.
    UserCancelled { request_id: String },
    /// The user's clipboard data.
    ClipboardData { request_id: String, data: String },
    /// The user's password submission (for service stop).
    PasswordSubmit {
        request_id: String,
        password: String,
    },
    /// The user cancelled the password dialog.
    PasswordCancel { request_id: String },
    /// Heartbeat pong in response to agent `Ping`.
    Pong,
}

// ─────────────────────────────────────────────────────────────────────────────
// Pipe 2 — DLPEventAgent2UI (agent → UI, fire-and-forget)
// ─────────────────────────────────────────────────────────────────────────────

/// Messages sent FROM the agent TO the UI over Pipe 2.
///
/// These are one-way notifications — the UI does not reply.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload")]
pub enum Pipe2AgentMsg {
    /// Display a toast notification.
    Toast { title: String, body: String },
    /// Update the agent status shown in the UI tray/icon.
    StatusUpdate { status: String },
    /// The UI should respond with HEALTH_PONG over Pipe 3.
    HealthPing,
    /// The UI process is unhealthy — the agent will kill and respawn it.
    UiRespawn { session_id: u32 },
    /// The session is ending — the UI should run its closing sequence and exit.
    UiClosingSequence { session_id: u32 },
    /// Broadcast by the agent after each heartbeat attempt to dlp-server.
    /// The UI uses this to display Agent->Server connection state in the tray tooltip.
    ServerConnected { connected: bool },
}

// ─────────────────────────────────────────────────────────────────────────────
// Pipe 3 — DLPEventUI2Agent (UI → agent, one-way)
// ─────────────────────────────────────────────────────────────────────────────

/// Messages sent FROM the UI TO the agent over Pipe 3.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload")]
#[allow(clippy::large_enum_variant)]
pub enum Pipe3UiMsg {
    /// The UI is alive — sent in response to HEALTH_PING or periodically.
    HealthPong,
    /// The UI is initialised and ready.
    UiReady { session_id: u32 },
    /// The UI is closing (user logged out or closed voluntarily).
    UiClosing { session_id: u32 },
    /// Clipboard paste detected with sensitive content.
    ClipboardAlert {
        /// Session ID where the paste occurred.
        session_id: u32,
        /// Classification tier of the pasted content.
        classification: String,
        /// Truncated preview of the pasted text.
        preview: String,
        /// Total length of the pasted text.
        text_length: usize,
        /// Identity of the application that initiated the clipboard operation
        /// (populated by Phase 25's source-resolver).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source_application: Option<AppIdentity>,
        /// Identity of the application that received the paste
        /// (populated by Phase 25's destination-resolver).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        destination_application: Option<AppIdentity>,
    },
    /// Drag-and-drop operation blocked or alerted (Phase 40).
    DragDropAlert {
        /// Session ID where the drop occurred.
        session_id: u32,
        /// Classification tier of the dragged content.
        classification: String,
        /// Identity of the source application.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source_application: Option<AppIdentity>,
        /// Identity of the destination application.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        destination_application: Option<AppIdentity>,
        /// Truncated preview of the dragged data.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        data_preview: Option<String>,
    },
}

