/// Starts a [`HookIpcServer`] on a dedicated thread using the given
/// handler, waits until the pipe is created, and returns the thread
/// handle so the caller can join it later.
fn start_server(
    pipe_name: &str,
    handler: HookHandler,
) -> std::thread::JoinHandle<Result<()>> {
    let name = pipe_name.to_string();
    let handle = std::thread::spawn(move || {
        let server = HookIpcServer::new(name, handler);
        server.run()
    });

    // Wait for the server to create the pipe before returning.
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        match connect_client(pipe_name) {
            Ok(c) => {
                close_pipe(c);
                return handle;
            }
            Err(e) => {
                eprintln!("[start_server] waiting for {}: {}", pipe_name, e);
            }
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    panic!("server did not create pipe within 5s");
}

